style.css:
@-moz-document url-prefix("https://www.youtube.com/") {
/* Base background */
    body {
        background-color: #ffe6f0 !important; /* pastel pink */
    }

    /* Transparent app wrapper */
    ytd-app, #background {
        background-color: transparent !important;
    }

    /* Header / Top bar */
    ytd-masthead, #masthead-container {
        background-color: #ffccdd !important;
        box-shadow: none !important;
    }

    #container.ytd-masthead, .ytd-masthead {
        border-bottom: 2px solid #ffb6c1 !important;
    }

    /* Side menu cute background */
    ytd-mini-guide-renderer, ytd-guide-renderer {
        background-color: #fff0f5 !important;
    }

    /* Optional: text color cleanup */
    * {
        color: #333 !important;
    }

    /* Optional: cute scroll bar */
    ::-webkit-scrollbar {
        width: 8px;
    }

    ::-webkit-scrollbar-track {
        background: #ffe6f0;
    }

    ::-webkit-scrollbar-thumb {
        background-color: #ff99cc;
        border-radius: 10px;
    }
}
